verus! {
    use std::vec::Vec;

    /// Given a nonempty vector `a` of 8‐bit signed integers,
    /// returns the index of the first occurrence of the minimum element.
    ///
    /// Specification:
    ///   - The input vector is nonempty.
    ///   - The result is a valid index into `a`.
    ///   - `a[result]` is ≤ every other element of `a`.
    ///   - All elements strictly before `result` are strictly greater than `a[result]`.
    fn argmin(a: Vec<i8>) -> usize
        requires
            a.len() > 0,
        ensures
            // result is in bounds
            result < a.len(),
        ensures
            // a[result] is a global minimum
            #[trigger] forall |i: usize| i < a.len() ==> a[result] <= a[i],
        ensures
            // it's the *first* occurrence of that minimum
            #[trigger] forall |j: usize| j < result ==> a[j] > a[result],
    {
        let mut min_idx: usize = 0;
        let mut i:       usize = 1;

        // We scan from i=1 up to a.len(), always maintaining:
        //  1) 1 ≤ i ≤ a.len()
        //  2) min_idx < i
        //  3) for all k < i, a[min_idx] ≤ a[k]
        //  4) for all j < min_idx, a[j] > a[min_idx]
        while i < a.len() {
            invariant
                i <= a.len();
            invariant
                min_idx < i;
            invariant
                #[trigger] forall |k: usize| k < i ==> a[min_idx] <= a[k];
            invariant
                #[trigger] forall |j: usize| j < min_idx ==> a[j] > a[min_idx];
            decreases
                a.len() - i;

            // If we found a strictly smaller element, record its index
            if a[i] < a[min_idx] {
                min_idx = i;
            }
            i += 1;
        }

        // At loop exit, i == a.len(), so
        //   • min_idx < a.len()
        //   • ∀ k < a.len(): a[min_idx] ≤ a[k]
        //   • ∀ j < min_idx: a[j] > a[min_idx]
        // exactly matching our postconditions.
        min_idx
    }
}